<header class="citybar"><div class="topin"><a class="citybrand" href="https://www.skutec.cz/"><span class="cityidentity"><img src="<?=BASE_PATH?>/assets/logo-skutec.png" alt="Město Skuteč"></span></a><a class="cityback" href="https://www.skutec.cz/">← Zpět na web města</a></div></header>
<header class="top"><div class="topin"><a href="<?=BASE_PATH?>/issue.php?id=<?=urlencode($issue['id'])?>">← OBSAH VYDÁNÍ</a><span><?=sprintf('%02d/%d',$issue['month'],$issue['year'])?></span></div></header>
<main class="wrap article"><i class="cat cat-<?=htmlspecialchars($article['category']??'ostatni')?>"><?=htmlspecialchars($article['categoryLabel']??'Ostatní')?></i><h1><?=htmlspecialchars($article['title'])?></h1>
<?php if(!$visual&&!empty(trim($article['text']??''))):?><div class="audio"><button class="primary" onclick="speak()">▶ Přečíst nahlas</button><button onclick="speechSynthesis.pause()">Pauza</button><button onclick="speechSynthesis.resume()">Pokračovat</button><button onclick="speechSynthesis.cancel()">Stop</button></div><?php endif;?>
