<?php if($visual&&empty($article['content'])&&isset($article['media'][0])):?><figure><img src="<?=BASE_PATH?>/<?=htmlspecialchars($article['media'][0]['src'])?>" alt=""></figure><?php endif;?>
</div><?php if($related):?><section class="related"><h2>Související články</h2><div class="grid articles"><?php foreach($related as $r):$ra=$r['article'];$ri=$r['issue'];?><a class="card" href="<?=BASE_PATH?>/article.php?issue=<?=urlencode($ri['id'])?>&amp;slug=<?=urlencode($ra['slug']??slugify($ra['title']))?>"><i class="cat cat-<?=htmlspecialchars($ra['category']??'ostatni')?>"><?=htmlspecialchars($ra['categoryLabel']??'Ostatní')?></i><h2><?=htmlspecialchars($ra['title'])?></h2><p><?=sprintf('%02d/%d',$ri['month'],$ri['year'])?></p></a><?php endforeach;?></div></section><?php endif;?><nav class="articleNav"><?php if($prev):?><a href="<?=BASE_PATH?>/article.php?issue=<?=urlencode($issue['id'])?>&amp;slug=<?=urlencode($prev['slug']??slugify($prev['title']))?>">← <small>Předchozí</small><b><?=htmlspecialchars($prev['title'])?></b></a><?php else:?><span></span><?php endif;?><?php if($next):?><a class="next" href="<?=BASE_PATH?>/article.php?issue=<?=urlencode($issue['id'])?>&amp;slug=<?=urlencode($next['slug']??slugify($next['title']))?>"><small>Další</small><b><?=htmlspecialchars($next['title'])?></b> →</a><?php endif;?></nav></main>
